def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'
    if n >= 99:
        return 'D'

    my = [h[0] for h in history]
    op = [h[1] for h in history]

    op_d = 0
    for x in op:
        if x == 'D':
            op_d += 1
    op_c = n - op_d

    last_op = op[-1]
    last_my = my[-1]

    rs = n - 10
    if rs < 0:
        rs = 0
    last10_d = 0
    for x in op[rs:]:
        if x == 'D':
            last10_d += 1
    rl = n - rs
    if rl < 1:
        rl = 1

    prior_all = op_d / float(n)
    prior_recent = last10_d / float(rl)
    prior = 0.65 * prior_recent + 0.35 * prior_all

    run_dd = 0
    i = n - 1
    while i >= 0 and my[i] == 'D' and op[i] == 'D':
        run_dd += 1
        i -= 1

    run_cd = 0
    i = n - 1
    while i >= 0 and my[i] == 'C' and op[i] == 'D':
        run_cd += 1
        i -= 1

    run_dc = 0
    i = n - 1
    while i >= 0 and my[i] == 'D' and op[i] == 'C':
        run_dc += 1
        i -= 1

    run_cc = 0
    i = n - 1
    while i >= 0 and my[i] == 'C' and op[i] == 'C':
        run_cc += 1
        i -= 1

    run_op_c = 0
    i = n - 1
    while i >= 0 and op[i] == 'C':
        run_op_c += 1
        i -= 1

    after_C = 0
    after_C_D = 0
    after_D = 0
    after_D_D = 0

    sd00 = sd01 = sd10 = sd11 = 0
    st00 = st01 = st10 = st11 = 0

    for i in range(n - 1):
        pm = my[i]
        om = op[i]
        nxt = op[i + 1]
        nd = 1 if nxt == 'D' else 0

        if pm == 'D':
            after_D += 1
            if nd == 1:
                after_D_D += 1
        else:
            after_C += 1
            if nd == 1:
                after_C_D += 1

        if pm == 'C':
            if om == 'C':
                st00 += 1
                sd00 += nd
            else:
                st01 += 1
                sd01 += nd
        else:
            if om == 'C':
                st10 += 1
                sd10 += nd
            else:
                st11 += 1
                sd11 += nd

    wC = 6.0 - 0.5 * float(after_C)
    if wC < 2.0:
        wC = 2.0
    qC = (float(after_C_D) + wC * prior) / float(after_C + wC)
    if qC < 0.0:
        qC = 0.0
    elif qC > 1.0:
        qC = 1.0

    if after_D == 0:
        priorD = 0.78 + 0.17 * prior
    elif after_D < 3:
        priorD = 0.72 + 0.17 * prior
    else:
        priorD = 0.45 + 0.25 * prior

    if priorD < 0.40:
        priorD = 0.40
    elif priorD > 0.95:
        priorD = 0.95

    wD = 6.0 - 0.5 * float(after_D)
    if wD < 2.0:
        wD = 2.0
    qD = (float(after_D_D) + wD * priorD) / float(after_D + wD)
    if qD < 0.0:
        qD = 0.0
    elif qD > 1.0:
        qD = 1.0

    if last_my == 'C':
        q_cur = qC
        if last_op == 'C':
            st_now = st00
            sd_now = sd00
        else:
            st_now = st01
            sd_now = sd01
    else:
        q_cur = qD
        if last_op == 'C':
            st_now = st10
            sd_now = sd10
        else:
            st_now = st11
            sd_now = sd11

    p_now = (float(sd_now) + 4.0 * q_cur) / float(st_now + 4.0)
    if p_now < 0.0:
        p_now = 0.0
    elif p_now > 1.0:
        p_now = 1.0

    if op_c == 0 and op_d >= 3:
        return 'D'

    if n >= 20 and op_c <= 2 and op_d * 10 >= n * 8:
        return 'D'

    if n >= 25 and last10_d >= 9 and op_c <= max(3, int(0.12 * n)):
        return 'D'

    if qD >= 0.92 and qC >= 0.55:
        return 'D'

    if op_c == n and run_dc >= 1 and run_dc <= 5 and last_my == 'D' and last_op == 'C':
        return 'D'

    if op_c == n and run_cc >= 35 and n >= 45 and rng.random() < 0.15:
        return 'D'

    if run_cd >= 3:
        return 'D'

    if (
        run_dd >= 2
        and qD >= 0.55
        and qC < 0.72
        and op_c >= max(3, int(0.08 * n))
    ):
        return 'C'

    if (
        run_dd >= 4
        and qC < 0.80
        and op_c >= max(2, int(0.05 * n))
    ):
        return 'C'

    if (
        after_D >= 3
        and qD <= 0.42
        and qD <= qC + 0.22
        and op_c > 0
        and last10_d <= 7
    ):
        return 'D'

    if (
        run_dc >= 2
        and after_D >= 2
        and qD <= 0.55
        and qD <= qC + 0.30
        and last10_d <= 8
    ):
        return 'D'

    rem = 100 - n
    if rem <= 0:
        return 'D'

    v0 = [0.0] * rem
    v1 = [0.0] * rem

    for r in range(1, rem):
        p = qC
        c0 = 3.0 * (1.0 - p) + v0[r - 1]
        d0 = (5.0 - 4.0 * p) + v1[r - 1]
        v0[r] = c0 if c0 >= d0 else d0

        p = qD
        c1 = 3.0 * (1.0 - p) + v0[r - 1]
        d1 = (5.0 - 4.0 * p) + v1[r - 1]
        v1[r] = c1 if c1 >= d1 else d1

    valC = 3.0 * (1.0 - p_now) + v0[rem - 1]
    valD = (5.0 - 4.0 * p_now) + v1[rem - 1]

    if valD > valC + 0.20:
        return 'D'
    if valC > valD + 0.20:
        return 'C'

    if last_op == 'D':
        return 'D'
    return 'C'
